    """Apply the transformation based on demo pairs"""
    rows = len(input_grid)
    cols = len(input_grid[0])

    # Initialize output with same dimensions
    output = [[0]*cols for _ in range(rows)]

    # 8-rectangle rule: fill checkerboard of 3 where (r+c)%2==0
    # Rectangle: rows 1-4, cols 1-7
    for r in range(1, 5):
        for c in range(1, 8):
            if r in (1, 4) or c in (1, 7):
                # Border - keep original value
                if input_grid[r][c] == 8:
                    output[r][c] = 8
            else:
                # Interior - checkerboard fill
                if (r + c) % 2 == 0:
                    output[r][c] = 3
                else:
                    output[r][c] = 0

    # 4-rectangle rule: rows 6-13, cols 12-18
    # Pattern observed: alternating checkerboard based on (c-r)%2
    for r in range(6, 14):
        for c in range(12, 19):
            if r in (6, 13) or c in (12, 18):
                # Border - keep original
                if input_grid[r][c] == 4:
                    output[r][c] = 4
            else:
                # Interior - complex pattern
                # Odd rows (7,9,11,13): 6 at cols 14,16 or 13,15,17
                # Even rows (8,10,12): 6 at cols 15,17 or 14,16
                # The pattern shifts based on (c - 7*r) % 4 or similar

                # Let me try: 6 when (c - r) % 4 is in certain positions
                offset = (c - r) % 4
                if offset == 1 or offset == 3:
                    output[r][c] = 6
                else:
                    output[r][c] = 0

    return output

